// src/components/Dashboard.js
import React from 'react';
import { Link } from 'react-router-dom';
import './Dashboard.css';

const Dashboard = ({ user, onLogout }) => {
  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <div className="welcome-message">
          <h1>Welcome, {user?.username === 'doctor' ? 'ER Doctor' : 'ER Nurse'}</h1>
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <span className="user-role">{user?.username === 'doctor' ? 'Doctor' : 'Nurse'}</span>
            <button onClick={onLogout} className="logout-button" style={{ marginLeft: '10px' }}>
              Logout
            </button>
          </div>
        </div>
        
        <div className="quick-actions">
          <Link to="/patient/new" className="action-button primary">
            New Patient
          </Link>
          <Link to="/queue" className="action-button secondary">
            View Queue
          </Link>
        </div>
      </div>
      
      {/* Rest of your Dashboard component */}
    </div>
  );
};

export default Dashboard;
